fun deposit_underlying<MarketType, CoinType>(
    self: &mut Reserve<MarketType>,
    coin: Coin<CoinType>,
) {
    let reserve_token_balance: &mut ReserveBalance<MarketType, CoinType> = dynamic_field::borrow_mut(&mut self.id, ReserveBalanceKey{});

    self.cash = self.cash + coin.value();
    reserve_token_balance.underlying_balance.join(coin.into_balance());
}

fun withdraw_underlying<MarketType, CoinType>(
    self: &mut Reserve<MarketType>,
    amount: u64,
): Balance<CoinType> {
    let reserve_token_balance: &mut ReserveBalance<MarketType, CoinType> = dynamic_field::borrow_mut(&mut self.id, ReserveBalanceKey{});

    self.cash = self.cash - amount;
    assert!(self.cash >= self.cash_reserve.ceil(), error::market_cash_reserve_not_enough());

    reserve_token_balance.underlying_balance.split(amount)
}

fun flash_loan_withdraw<MarketType, CoinType>(
    self: &mut Reserve<MarketType>,
    amount: u64,
): Balance<CoinType> {
    let reserve_token_balance: &mut ReserveBalance<MarketType, CoinType> = dynamic_field::borrow_mut(&mut self.id, ReserveBalanceKey{});
    reserve_token_balance.underlying_balance.split(amount)
}

#[test_only]
public struct BTC {}

#[test_only]
public struct SUI {}

#[test_only]
public struct USDC {}

#[test_only]
public struct MainMarket {}

#[test_only]
public struct DummyMarket {}

#[test_only]
fun set_borrow_index<MarketType>(self: &mut Reserve<MarketType>, value: Decimal, now: u64) {
    self.borrow_index.set_value(value, now);
}

#[test_only]
fun ensure_invariants_hold<MarketType, CoinType>(self: &Reserve<MarketType>,) {
    assert!(self.cash >= self.cash_reserve.floor());

    let reserve_token_balance: &ReserveBalance<MarketType, CoinType> = dynamic_field::borrow(&self.id, ReserveBalanceKey{});

    assert!(self.cash == reserve_token_balance.underlying_balance.value());
    assert!(self.total_supply >= reserve_token_balance.ctoken_supply.supply_value());
}

